-- GENERATED by scripts/launch/gen-012.js. Do not edit by hand.
-- parcels_current: the one view every app query reads. parcels_v2 (geometry, keys) LEFT JOIN dor.nal_2026 (attributes)
-- + dor.sales_last3 (last 3 qualified sales). Column names match what the app used on parcels (v1); see docs/parcels_current_mapping.md.
--   Volusia joins NAL through ALT_KEY (v2's Volusia key is the county ALT_KEY); every other county joins on match_key.
--   NAL rows that are strict-key duplicates (Marion, Brevard) join on the separator-preserving key (dor.nal_dupes).
--   parcels_current_nogeom = NAL parcels with no v2 row (new 2026 parcels, no geometry); parcels_current_all = both.
DROP VIEW IF EXISTS parcels_current_all;
DROP VIEW IF EXISTS parcels_current_nogeom;
DROP VIEW IF EXISTS parcels_current;
DROP VIEW IF EXISTS dor.nal_current;

CREATE VIEW dor.nal_current AS
SELECT n.*, d.sep_key FROM dor.nal_2026 n LEFT JOIN dor.nal_dupes d ON d.co_no = n.co_no AND d.seq_no = n.seq_no;

CREATE VIEW parcels_current AS
SELECT
  v.id AS gid,
  'FL'::char(2) AS state,
  v.co_no AS co_no,
  'FL-' || v.parcel_key AS parcel_key,
  v.parcel_key AS parcel_key_local,
  v.match_key AS match_key,
  v.county AS county,
  COALESCE(v.parcel_id, v.parcelno_legacy) AS parcel_id,
  v.parcelno_legacy AS parcelno,
  n.alt_key AS alt_key,
  n.own_name AS own_name,
  n.own_addr1 AS own_addr1,
  n.own_addr2 AS own_addr2,
  n.own_city AS own_city,
  n.own_state AS own_state,
  n.own_zipcd AS own_zipcd,
  n.phy_addr1 AS phy_addr1,
  n.phy_addr2 AS phy_addr2,
  n.phy_city AS phy_city,
  n.phy_zipcd AS phy_zipcd,
  round(n.lnd_sqfoot / 43560.0, 4) AS acreage,
  n.dor_uc AS dor_uc,
  n.dor_uc AS use_code,
  n.jv AS jv,
  n.lnd_val AS land_value,
  n.act_yr_blt AS year_built,
  n.eff_yr_blt AS eff_year_built,
  n.tot_lvg_area AS living_area_sqft,
  (n.exmpt_01 > 0) AS homestead,
  s.sale1_date AS sale1_date,
  s.sale1_price AS sale_prc1,
  EXTRACT(year FROM s.sale1_date)::int AS sale_yr1,
  to_char(s.sale1_date, 'MM') AS sale_mo1,
  s.sale2_date AS sale2_date,
  s.sale2_price AS sale_prc2,
  EXTRACT(year FROM s.sale2_date)::int AS sale_yr2,
  to_char(s.sale2_date, 'MM') AS sale_mo2,
  s.sale3_date AS sale3_date,
  s.sale3_price AS sale_prc3,
  NULL::numeric AS distance_to_highway,
  ST_Y(ST_PointOnSurface(v.geom)) AS latitude,
  ST_X(ST_PointOnSurface(v.geom)) AS longitude,
  v.geom AS geom,
  true AS has_geom,
  v.needs_review AS needs_review
FROM parcels_v2 v
LEFT JOIN dor.nal_current n
       ON n.co_no = v.co_no AND n.match_key = v.match_key
      AND (n.sep_key IS NULL OR n.sep_key = substr(v.parcel_key, length(v.co_no::text) + 2))
LEFT JOIN dor.sales_last3 s ON s.co_no = v.co_no AND s.join_key = v.match_key
WHERE NOT v.quarantine
 AND v.county <> 'Volusia'
UNION ALL
SELECT
  v.id AS gid,
  'FL'::char(2) AS state,
  v.co_no AS co_no,
  'FL-' || v.parcel_key AS parcel_key,
  v.parcel_key AS parcel_key_local,
  v.match_key AS match_key,
  v.county AS county,
  COALESCE(v.parcel_id, v.parcelno_legacy) AS parcel_id,
  v.parcelno_legacy AS parcelno,
  n.alt_key AS alt_key,
  n.own_name AS own_name,
  n.own_addr1 AS own_addr1,
  n.own_addr2 AS own_addr2,
  n.own_city AS own_city,
  n.own_state AS own_state,
  n.own_zipcd AS own_zipcd,
  n.phy_addr1 AS phy_addr1,
  n.phy_addr2 AS phy_addr2,
  n.phy_city AS phy_city,
  n.phy_zipcd AS phy_zipcd,
  round(n.lnd_sqfoot / 43560.0, 4) AS acreage,
  n.dor_uc AS dor_uc,
  n.dor_uc AS use_code,
  n.jv AS jv,
  n.lnd_val AS land_value,
  n.act_yr_blt AS year_built,
  n.eff_yr_blt AS eff_year_built,
  n.tot_lvg_area AS living_area_sqft,
  (n.exmpt_01 > 0) AS homestead,
  s.sale1_date AS sale1_date,
  s.sale1_price AS sale_prc1,
  EXTRACT(year FROM s.sale1_date)::int AS sale_yr1,
  to_char(s.sale1_date, 'MM') AS sale_mo1,
  s.sale2_date AS sale2_date,
  s.sale2_price AS sale_prc2,
  EXTRACT(year FROM s.sale2_date)::int AS sale_yr2,
  to_char(s.sale2_date, 'MM') AS sale_mo2,
  s.sale3_date AS sale3_date,
  s.sale3_price AS sale_prc3,
  NULL::numeric AS distance_to_highway,
  ST_Y(ST_PointOnSurface(v.geom)) AS latitude,
  ST_X(ST_PointOnSurface(v.geom)) AS longitude,
  v.geom AS geom,
  true AS has_geom,
  v.needs_review AS needs_review
FROM parcels_v2 v
LEFT JOIN dor.nal_current n
       ON n.co_no = v.co_no AND n.co_no = 74 AND upper(regexp_replace(n.alt_key, '[^A-Za-z0-9]', '', 'g')) = v.match_key
      AND (n.sep_key IS NULL OR n.sep_key = substr(v.parcel_key, length(v.co_no::text) + 2))
LEFT JOIN dor.sales_last3 s ON s.co_no = v.co_no AND s.join_key = v.match_key
WHERE NOT v.quarantine
 AND v.county = 'Volusia' AND v.co_no = 74;

CREATE VIEW parcels_current_nogeom AS
SELECT
  -(n.co_no::bigint * 10000000 + n.seq_no) AS gid,
  'FL'::char(2) AS state,
  n.co_no::smallint AS co_no,
  'FL-' || n.co_no || '-' || normalize_parcel_id_sep(n.parcel_id, cc.name) AS parcel_key,
  n.co_no || '-' || normalize_parcel_id_sep(n.parcel_id, cc.name) AS parcel_key_local,
  n.match_key AS match_key,
  cc.name AS county,
  n.parcel_id AS parcel_id,
  n.parcel_id AS parcelno,
  n.alt_key AS alt_key,
  n.own_name AS own_name,
  n.own_addr1 AS own_addr1,
  n.own_addr2 AS own_addr2,
  n.own_city AS own_city,
  n.own_state AS own_state,
  n.own_zipcd AS own_zipcd,
  n.phy_addr1 AS phy_addr1,
  n.phy_addr2 AS phy_addr2,
  n.phy_city AS phy_city,
  n.phy_zipcd AS phy_zipcd,
  round(n.lnd_sqfoot / 43560.0, 4) AS acreage,
  n.dor_uc AS dor_uc,
  n.dor_uc AS use_code,
  n.jv AS jv,
  n.lnd_val AS land_value,
  n.act_yr_blt AS year_built,
  n.eff_yr_blt AS eff_year_built,
  n.tot_lvg_area AS living_area_sqft,
  (n.exmpt_01 > 0) AS homestead,
  NULL::date AS sale1_date,
  NULL::bigint AS sale_prc1,
  NULL::int AS sale_yr1,
  NULL::text AS sale_mo1,
  NULL::date AS sale2_date,
  NULL::bigint AS sale_prc2,
  NULL::int AS sale_yr2,
  NULL::text AS sale_mo2,
  NULL::date AS sale3_date,
  NULL::bigint AS sale_prc3,
  NULL::numeric AS distance_to_highway,
  NULL::float8 AS latitude,
  NULL::float8 AS longitude,
  NULL::geometry(MultiPolygon,4326) AS geom,
  false AS has_geom,
  false AS needs_review
FROM dor.nal_current n
JOIN county_codes cc ON cc.co_no = n.co_no
WHERE NOT EXISTS (
  SELECT 1 FROM parcels_v2 v WHERE v.co_no = n.co_no AND NOT v.quarantine
     AND v.match_key = CASE WHEN n.co_no = 74 THEN upper(regexp_replace(n.alt_key, '[^A-Za-z0-9]', '', 'g')) ELSE n.match_key END
     AND (n.sep_key IS NULL OR n.sep_key = substr(v.parcel_key, length(v.co_no::text) + 2)));

CREATE VIEW parcels_current_all AS
SELECT * FROM parcels_current UNION ALL SELECT * FROM parcels_current_nogeom;
